def convert_to_base(num, base):
    if base < 2 or base > 36:
        raise ValueError("Base must be between 2 and 36")
    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if num == 0:
        return "0"
    neg = num < 0
    num = abs(num)
    res = []
    while num > 0:
        res.append(digits[num % base])
        num //= base
    if neg:
        res.append('-')
    return ''.join(reversed(res))

