def make_palindrome_min_changes(s: str) -> str:
    """
    Return a palindrome formed by changing the minimum number of characters in s.
    When changing, pick the lexicographically smaller character to keep the palindrome
    as lexicographically small as possible.
    """
    s = list(s)
    i, j = 0, len(s) - 1
    while i < j:
        if s[i] != s[j]:
            # Change the larger character to the smaller one to minimize changes
            if s[i] < s[j]:
                s[j] = s[i]
            else:
                s[i] = s[j]
        i += 1
        j -= 1
    return ''.join(s)
