def smallest_diff_pair_at_least_x_apart(arr, x):
    # arr is zero-indexed, x is integer
    n = len(arr)
    if n < 2 or x < 1:
        return None

    sorted_with_index = sorted((val, idx) for idx, val in enumerate(arr))

    min_diff = None
    result_pair = None

    for i in range(n):
        val_i, idx_i = sorted_with_index[i]
        for j in range(i + 1, n):
            val_j, idx_j = sorted_with_index[j]
            if abs(idx_j - idx_i) >= x:
                curr_diff = abs(val_j - val_i)
                if min_diff is None or curr_diff < min_diff:
                    min_diff = curr_diff
                    result_pair = (val_i, val_j)
                if min_diff is not None and curr_diff > min_diff:
                    break

    return result_pair
